<?php
declare(strict_types=1);
require_once __DIR__.'/SourceMasterCommands.php';
use MapaSource\SourceMasterCommands as M; use MapaSource\SourceSync as S; use MapaSource\CommandRejected;
$host=getenv('QA_DB_HOST');if(!$host||!str_starts_with($host,'mapa-source-qa-'))throw new RuntimeException('Isolated QA required.');
$db=new PDO("mysql:host=$host;charset=utf8mb4",'root','DEMO-source-qa-only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$db->exec('CREATE DATABASE mapa_master_qa');$db->exec('USE mapa_master_qa');
$count=0;function ck($v,$s){global $count;if(!$v)throw new RuntimeException($s);echo 'PASS '.(++$count).' '.$s."\n";}function deny($f,$status,$s){try{$f();}catch(CommandRejected $e){ck($e->status===$status,$s);return;}throw new RuntimeException($s.' accepted');}
foreach(['drivers'=>'amb_drivers','ambulances'=>'ambulances'] as $dataset=>$table){$cols=[];foreach(S::fieldsFor(S::CONTRACT_V2)[$dataset] as $key)$cols[]=$key==='id'?'id INT AUTO_INCREMENT PRIMARY KEY':"$key VARCHAR(255) NULL";$db->exec("CREATE TABLE $table (".implode(',',$cols).') ENGINE=InnoDB');}
foreach(['phc'=>'phc_id VARCHAR(64),type VARCHAR(64)','type_ambulance'=>'id VARCHAR(64),type VARCHAR(64)','institute_type'=>'id VARCHAR(64)','mandals'=>'mandal_id VARCHAR(64)','secretariat'=>'secretariat_id VARCHAR(64),phc_id VARCHAR(64)','amb_daily_status'=>'id INT,ambulance_id INT','amb_trips'=>'id INT,daily_status_id INT,driver_id INT,drop_date DATE,drop_time TIME','amb_repairs'=>'id INT,ambulance_id INT','cad_dispatch_log'=>'id INT,ambulance_id INT,driver_id INT'] as $t=>$cols)$db->exec("CREATE TABLE $t ($cols) ENGINE=InnoDB");
$db->exec("CREATE TABLE mapa_source_commands (request_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,request_hash CHAR(64) NOT NULL,actor_id CHAR(36) NOT NULL,action_name VARCHAR(40) NOT NULL,record_id VARCHAR(64) NOT NULL,expected_revision CHAR(64) NOT NULL,receipt JSON NULL,changes_json JSON NULL,created_at DATETIME(6) NOT NULL,completed_at DATETIME(6) NULL) ENGINE=InnoDB");$db->exec(file_get_contents(__DIR__.'/dispatch-reservations.sql'));
$db->exec("INSERT INTO phc VALUES('A','PHC'),('B','PHC');INSERT INTO type_ambulance VALUES('special','Special');INSERT INTO institute_type VALUES('PHC');INSERT INTO mandals VALUES('M');INSERT INTO secretariat VALUES('SA','A')");
$actor='10000000-0000-4000-8000-000000000001';$actors=[$actor=>['actions'=>M::ACTIONS,'phc_ids'=>['A'],'vehicle_types'=>['Special'],'mandal_ids'=>['M']]];$secret=str_repeat('x',64);$seq=0;
$make=function($action,$values,$id='new')use($db,$actor,&$seq){$dataset=str_starts_with($action,'driver.')?'drivers':'ambulances';$table=$dataset==='drivers'?'amb_drivers':'ambulances';$rows=$db->query('SELECT '.implode(',',S::fieldsFor(S::CONTRACT_V2)[$dataset])." FROM $table")->fetchAll(PDO::FETCH_ASSOC);$revision=$id==='new'?M::collectionRevision($dataset,$rows):M::recordRevision($dataset,array_values(array_filter($rows,fn($r)=>(string)$r['id']===$id))[0]);return ['contract'=>M::CONTRACT,'company_id'=>S::COMPANY,'request_id'=>sprintf('20000000-0000-4000-8000-%012d',++$seq),'actor_id'=>$actor,'action'=>$action,'record_id'=>$id,'expected_revision'=>$revision,'values'=>$values];};
$run=fn($c)=>M::execute($db,$c,$actors,$secret);
$v=['name'=>'DEMO master driver','age'=>30,'gender'=>'Male','dob'=>null,'doj'=>null,'phc_id'=>'A','mobile_number'=>'9000000000','vehicle_type'=>'Special'];
$c=$make('driver.create',$v);$r=$run($c);ck($r['created_id']==='1','driver created');ck($run($c)==$r,'create retry returns same receipt');ck((int)$db->query('SELECT COUNT(*) FROM amb_drivers')->fetchColumn()===1,'retry does not duplicate');
$bad=$c;$bad['values']['name']='DEMO changed';deny(fn()=>$run($bad),409,'changed retry conflicts');$bad=$c;$bad['request_id']='30000000-0000-4000-8000-000000000001';deny(fn()=>$run($bad),409,'stale collection rejected');deny(fn()=>M::execute($db,$c,[],$secret),403,'revoked actor cannot replay');
$r2=$run($make('driver.create',$v));ck($r2['created_id']==='2','shared phone does not merge identity');$foreign=$v;$foreign['phc_id']='B';deny(fn()=>$run($make('driver.create',$foreign)),403,'foreign base denied');
$d=$make('driver.delete',['confirmed_label'=>'wrong'],'2');deny(fn()=>$run($d),422,'exact deletion label required');$d=$make('driver.delete',['confirmed_label'=>$v['name']],'2');$run($d);ck((int)$db->query('SELECT COUNT(*) FROM amb_drivers')->fetchColumn()===1,'unused driver deleted');ck($run($d)['request_id']===$d['request_id'],'delete retry idempotent');
$db->exec("INSERT INTO cad_dispatch_log VALUES(1,99,1)");deny(fn()=>$run($make('driver.delete',['confirmed_label'=>$v['name']],'1')),409,'driver history preserved');
$a=['vehicle_number'=>'DEMO1234','type_id'=>'special','institute_type_id'=>'PHC','phc_id'=>'A','mandal_id'=>null,'secretariat_id'=>null,'parking_type'=>'hospital','parking_place_name'=>null,'latitude'=>null,'longitude'=>null];$ar=$run($make('ambulance.create',$a));ck($ar['created_id']==='1','ambulance created');deny(fn()=>$run($make('ambulance.create',$a)),409,'duplicate registration blocked');$a['vehicle_number']='DEMO5678';$a['institute_type_id']='OTHER';deny(fn()=>$run($make('ambulance.create',$a)),422,'institute parent mismatch blocked');
$db->exec('INSERT INTO amb_repairs VALUES(1,1)');deny(fn()=>$run($make('ambulance.delete',['confirmed_label'=>'DEMO1234'],'1')),409,'repair history preserved');
$ledger=$db->query('SELECT receipt,changes_json FROM mapa_source_commands')->fetchAll(PDO::FETCH_ASSOC);ck(!str_contains(json_encode($ledger),'9000000000')&&!str_contains(json_encode($ledger),'DEMO master driver'),'ledger excludes private roster values');
echo "SOURCE MASTER PASS $count checks\n";
